{
  "issues": [],
  "profile": {
    "personality": {
      "traits": ["踏实肯干", "寡言少语", "循规蹈矩"],
      "values": ["家人平安", "手艺不欺客"],
      "flaws": ["遇事容易钻牛角尖"]
    },
    "voice": {
      "register": "市井口语，简短直接",
      "accent": "南市水岸一带的软尾音，语速偏慢",
      "habits": ["说话前先搓手上的面粉", "应和时只点头不吭声"],
      "samples": ["面发过了，这炉得重来。", "阿桂，把摊子收了，风大。", "爹，您坐着，我给您端过去。"]
    },
    "background": "自小在南市水岸边长大，跟着长辈学烘麦饼，一烘就是几十年。每天天不亮起身和面，守着炉子到日头偏西。客舍洗晒和摊位整理的活计也接，挣的是手脚勤快的钱。家里有老父贺峰和子女贺桂，日子过得紧巴却安稳，最怕炉火不匀、饼烘焦了。",
    "currentConcern": "老父近来腿脚发沉，收摊后得多绕路去客舍取热水给他敷。",
    "goals": ["把烘饼的火候守稳，不叫老客摇头", "攒些气力，让贺桂日后不必只守着这炉子"],
    "fears": ["老父一病不起，自己却腾不出手照看"],
    "knowledge": {
      "unknown": ["南市以外各坊的行情与人事", "麦饼除烘烤之外的其他做法"]
    },
    "relationships": [
      {
        "with": "npc_pop_bs_001_2",
        "relation": "子女",
        "note": "贺桂常来摊上帮手收拣，他嘴上不夸，心里认这个孩子肯吃苦。"
      },
      {
        "with": "npc_pop_bs_001_3",
        "relation": "父母",
        "note": "贺峰年迈，他每日收摊必先回家看老父，端水递饼从不落空。"
      }
    ],
    "visibleFeature": "双手掌心和指节覆着厚茧，常年沾着洗不净的面粉白印，右眉尾有一道浅疤。"
  }
}
